// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract InvMutTest is Test {
    demo c;
    function setUp() public { c = new demo(); }

    // fuzz the 'from' address and the array length/content via a bytes32 seed and an address
    function testFuzz_property(address from, bytes32 seed, uint8 tosLen) public {
        // keep tosLen in a reasonable wide range but allow zero to be excluded by vm.assume below
        tosLen = uint8(bound(tosLen, 0, 10));
        // build an array of addresses derived from seed so fuzzer can vary contents
        address[] memory tos = new address[](tosLen == 0 ? 0 : tosLen);
        for (uint i = 0; i < tos.length; i++) {
            // derive addresses from seed + i to avoid hard-coding any particular callee
            tos[i] = address(uint160(uint256(keccak256(abi.encodePacked(seed, i)))));
        }

        // We need at least one recipient to exercise the loop in the reference contract
        vm.assume(tos.length > 0);

        // Call transfer and observe whether it succeeds (reference should succeed for all such inputs)
        bool ok;
        try c.transfer(from, address(0x1234), tos, 1) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: for any admissible input (non-empty tos), the reference C completes (ok == true).
        // The mutant that reverts unconditionally after require will make ok == false for these inputs,
        // so this assertion will fail on that mutant for some fuzzed inputs.
        assertTrue(ok);
    }
}
